informal_sketch.pseudocode:
class Task:
    def __init__(self, id):
        self.id = id
        # Other task parameters will be added later

class Task:
    def __init__(self, id, period):
        self.id = id
        self.T = period

class Task:
    def __init__(self, id, period, deadline):
        self.id = id
        self.T = period
        self.D = deadline

class Task:
    def __init__(self, id, period, deadline, assurance_level):
        self.id = id
        self.T = period
        self.D = deadline
        self.L = assurance_level

class Task:
    def __init__(self, id, period, deadline, assurance_level, wcet_levels):
        self.id = id
        self.T = period
        self.D = deadline
        self.L = assurance_level
        self.C_levels = wcet_levels # A dictionary like {'A': 10, 'B': 8, 'C': 5, 'D': 3}

def validate_task_properties(task_set):
    for task_i in task_set:
        if task_i.D > task_i.T:
            return False # Deadline exceeds period
        if not (task_i.C_levels['A'] >= task_i.C_levels['B'] and \
                task_i.C_levels['B'] >= task_i.C_levels['C'] and \
                task_i.C_levels['C'] >= task_i.C_levels['D']):
            return False # WCETs not ordered by assurance level
    return True

def calculate_response_time(task_i, task_set):
    R_i_current = task_i.C_levels[task_i.L] # Initial guess: own WCET at its assurance level
    while True:
        R_i_next = 0
        for task_j in task_set:
            if task_j.rho <= task_i.rho: # Higher or equal priority tasks
                # Use task_i's assurance level for all interfering tasks
                C_j_for_analysis = task_j.C_levels[task_i.L]
                num_jobs = math.ceil(R_i_current / task_j.T)
                R_i_next += num_jobs * C_j_for_analysis

        if R_i_next == R_i_current:
            return R_i_current # Fixed point found
        if R_i_next > task_i.D:
            return R_i_next # Exceeds deadline, unschedulable

        R_i_current = R_i_next

def calculate_critical_scaling_factor(task_set, schedulability_test_func, initial_s=1.0, step=0.01):
    current_s = initial_s
    delta_star = initial_s
    while True:
        scaled_task_set = deepcopy(task_set)
        for task in scaled_task_set:
            for level in task.C_levels:
                task.C_levels[level] *= current_s

        if schedulability_test_func(scaled_task_set):
            delta_star = current_s
            current_s += step
        else:
            break
    return delta_star
